"""Roman numeral conversion (1..3999)."""


def to_roman(n: int) -> str:
    """Convert an integer 1..3999 to a standard Roman numeral string."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError(f"integer expected, got {type(n).__name__}")
    if not (1 <= n <= 3999):
        raise ValueError(f"must be between 1 and 3999, got {n}")

    # Build lookup sorted by value descending so greedy works.
    _lookup = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    ]

    parts = []
    for value, symbol in _lookup:
        while n >= value:
            parts.append(symbol)
            n -= value
    return "".join(parts)


# ---------------------------------------------------------------------------
# from_roman – strict parser
# ---------------------------------------------------------------------------

def from_roman(s: str) -> int:
    """Convert a well-formed standard Roman numeral string to an integer."""
    if not isinstance(s, str):
        raise ValueError(f"string expected, got {type(s).__name__}")

    roman_values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}

    # Quick sanity: every character must be valid.
    if not s or not all(c in roman_values for c in s):
        raise ValueError(f"invalid characters in '{s}'")

    # A well-formed standard numeral never repeats I, X, C, M more than 3
    # times in a row; V, L, D are never repeated at all.
    # We enforce this by parsing with a regex that only accepts canonical forms.
    import re
    pattern = r"^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$"
    if not re.match(pattern, s):
        raise ValueError(f"not a well-formed Roman numeral: '{s}'")

    # Now convert normally.
    total = 0
    prev = 0
    for ch in reversed(s):
        val = roman_values[ch]
        if val < prev:
            total -= val
        else:
            total += val
        prev = val

    return total

